using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using System.Data;
using System.Collections;
using WebGlobal;
using SimsObject;
using SimsService;

namespace InformationWeb.Controls.Learning
{
    /// <summary>
    /// Bảng điểm tổng kết V2 - Dùng store giống WinForms frmSubjectMarkDetail
    /// </summary>
    public partial class SubjectMarkDetail_V2 : ControlBase
    {
        #region Const

        private const string PERMISSION_VIEW = "frmWebSubjectMarkDetail_View";

        #endregion

        #region Variables

        private DataTable dtbData = null;
        private DataTable dtbClassSubject = null;
        private DataTable dtbSubjectMark = null;
        private int intRegulationIDCurrent = 0;
        private bool bolHaveNormalSubject = false;
        private string strShowTestAverage = "1";
        private string strShowExam1 = "1";
        private string strShowExam2 = "1";
        private string strShowExam3 = "1";
        private string strShowExam = "1";
        private string strShowSummary1 = "1";
        private string strShowSummary2 = "1";
        private string strShowSummary3 = "1";
        private string strShowSummary = "1";
        private string strShowEthic = "1";

        #endregion

        #region Load Data

        private void LoadData()
        {
            dtbData = null;
            dtbClassSubject = null;
            dtbSubjectMark = null;
            lblMsg.Visible = false;
            lblContent.Text = "";
            lblStatistic.Visible = false;

            try
            {
                intRegulationIDCurrent = uClass.RegulationID;

                // Lấy danh sách môn học theo lớp/năm/học kỳ
                SIM_Class_Subject objClassSubject = new SIM_Class_Subject();
                dtbClassSubject = objClassSubject.SearchSimpleList("@ClassID", uClass.ClassID,
                                            "@YearID", uYearSemester.YearID,
                                            "@Semester", uYearSemester.Semester,
                                            "@NotListSpecialType", null,
                                            "@IsOnlyForScheduling", 0);

                if (dtbClassSubject == null || dtbClassSubject.Rows.Count == 0)
                {
                    lblMsg.Text = "Không có môn học nào trong điều kiện đã chọn!";
                    lblMsg.Visible = true;
                    return;
                }

                // Lấy danh sách sinh viên
                SIM_Student objStudent = new SIM_Student();
                bool? bolIsShowAllStudent = rdoAll.Checked;

                dtbData = objStudent.GetDataTable("SIM_Student_SearchForSummary",
                                                "@ClassID", uClass.ClassID,
                                                "@YearID", uYearSemester.YearID,
                                                "@Semester", uYearSemester.Semester,
                                                "@IsShowAllStudent", rdoAll.Checked);

                if (dtbData == null || dtbData.Rows.Count == 0)
                {
                    lblMsg.Text = "Không có sinh viên nào trong điều kiện đã chọn!";
                    lblMsg.Visible = true;
                    return;
                }

                // Lấy sổ điểm
                SIM_SubjectMark objSubjectMark = new SIM_SubjectMark();

                // Xử lý loại môn đặc biệt (tốt nghiệp văn hoá, chính trị tốt nghiệp, ...)
                string strListGraduationSpecialType = "," + Global.SubjectSpecialType.TotNghiepVanHoa
                                                    + "," + Global.SubjectSpecialType.ChinhTriTotNghiep
                                                    + "," + Global.SubjectSpecialType.TotNghiepLT
                                                    + "," + Global.SubjectSpecialType.TotNghiepTH + ",";

                // Lấy sổ điểm theo qui chế
                if (intRegulationIDCurrent == 43 || intRegulationIDCurrent == 99 || intRegulationIDCurrent == 44)
                {
                    // Tín chỉ: lấy theo ClassID + OrderLearning (1 nếu chkIsFirst)
                    int? intOrderLearning = null;
                    if (chkIsFirst.Checked)
                        intOrderLearning = 1;

                    dtbSubjectMark = objSubjectMark.SearchOfClass43("@ClassID", uClass.ClassID,
                                                                "@OrderLearning", intOrderLearning);
                }
                else
                {
                    if (chkIsFirst.Checked)
                        dtbSubjectMark = objSubjectMark.SearchFirst("@ClassID", uClass.ClassID);
                    else
                        dtbSubjectMark = objSubjectMark.SearchFinal("@ClassID", uClass.ClassID);
                }

                if (dtbSubjectMark == null)
                {
                    lblMsg.Text = "Việc lấy thông tin điểm bị lỗi!";
                    lblMsg.Visible = true;
                    return;
                }

                // Thêm cột SubjectIndex vào dtbClassSubject
                dtbClassSubject.Columns.Add("SubjectIndex", typeof(int));

                // Khởi tạo cột và điền dữ liệu
                BuildDataAndGrid();
                FillData();
                ExportToHTML();
                ExportStatistic();

                lblMsg.Text = "";
                lblMsg.Visible = false;
            }
            catch (Exception ex)
            {
                lblMsg.Text = "Lỗi khi tải dữ liệu: " + ex.Message;
                lblMsg.Visible = true;
            }
        }

        /// <summary>
        /// Tạo cột động theo danh sách môn học
        /// </summary>
        private void BuildDataAndGrid()
        {
            dtbData.Columns.Add("SummaryLearningMark", typeof(double));
            dtbData.Columns.Add("LearningLevel", typeof(string));

            bolHaveNormalSubject = false;
            int i = 1;
            foreach (DataRow drw in dtbClassSubject.Rows)
            {
                drw["SubjectIndex"] = i;
                int intSpecialType = Convert.ToInt32(drw["SpecialType"]);
                if (intSpecialType == Global.SubjectSpecialType.BinhThuong)
                    bolHaveNormalSubject = true;

                // Tạo cột cho từng môn
                dtbData.Columns.Add("TestAverage_" + i.ToString(), typeof(double));
                dtbData.Columns.Add("Exam1_" + i.ToString(), typeof(double));
                dtbData.Columns.Add("Summary1_" + i.ToString(), typeof(double));
                dtbData.Columns.Add("Exam2_" + i.ToString(), typeof(double));
                dtbData.Columns.Add("Summary2_" + i.ToString(), typeof(double));
                dtbData.Columns.Add("Exam3_" + i.ToString(), typeof(double));
                dtbData.Columns.Add("Summary3_" + i.ToString(), typeof(double));
                dtbData.Columns.Add("FinalExam_" + i.ToString(), typeof(double));
                dtbData.Columns.Add("FinalSummary_" + i.ToString(), typeof(double));
                dtbData.Columns.Add("OrderLearning_" + i.ToString(), typeof(double));
                dtbData.Columns.Add("LearningLevel_" + i.ToString(), typeof(string));
                dtbData.Columns.Add("OtherFinalSummary_" + i.ToString(), typeof(double));
                dtbData.Columns.Add("Passed_" + i.ToString(), typeof(bool));

                i++;
            }
        }

        /// <summary>
        /// Điền điểm vào DataTable
        /// </summary>
        private void FillData()
        {
            foreach (DataRow drw in dtbData.Rows)
            {
                double dblTotalMark = 0;
                int intUnitTextCount = 0;

                DataRow[] rows = dtbSubjectMark.Select("StudentID='" + drw["StudentID"].ToString() + "'");
                foreach (DataRow drw2 in rows)
                {
                    string strSubjectID = drw2["SubjectID"].ToString();
                    DataRow[] rowSubjects = dtbClassSubject.Select("SubjectID='" + strSubjectID + "'");
                    if (rowSubjects.Length > 0)
                    {
                        string strIndex = rowSubjects[0]["SubjectIndex"].ToString();
                        drw["OrderLearning_" + strIndex] = drw2["OrderLearning"];

                        if (drw2["IsIgnore"] != DBNull.Value && Convert.ToBoolean(drw2["IsIgnore"]))
                        {
                            // Môn miễn
                            drw["Summary1_" + strIndex] = -1;
                            drw["Summary2_" + strIndex] = -1;
                            drw["Summary3_" + strIndex] = -1;
                            drw["FinalSummary_" + strIndex] = -1;
                        }
                        else
                        {
                            if (intRegulationIDCurrent == 43 || intRegulationIDCurrent == 99 || intRegulationIDCurrent == 44)
                            {
                                // Tín chỉ
                                drw["FinalSummary_" + strIndex] = drw2["FinalSummary"];
                                drw["LearningLevel_" + strIndex] = drw2["LearningLevel"];
                                drw["OtherFinalSummary_" + strIndex] = drw2["OtherFinalSummary"];

                                if (drw2["OtherFinalSummary"].ToString() != "")
                                {
                                    int intUnitText = Convert.ToInt32(drw2["UnitText"]);
                                    dblTotalMark += Convert.ToDouble(drw2["OtherFinalSummary"]) * intUnitText;
                                    intUnitTextCount += intUnitText;
                                }
                            }
                            else
                            {
                                // Không phải tín chỉ
                                drw["TestAverage_" + strIndex] = drw2["TestAverage"];
                                drw["Exam1_" + strIndex] = drw2["Exam1"];
                                drw["Summary1_" + strIndex] = drw2["Summary1"];

                                if (chkIsFirst.Checked)
                                {
                                    // Chỉ xét lần 1
                                    drw["FinalSummary_" + strIndex] = drw2["Summary1"];

                                    if (drw2["Summary2"].ToString() != "" || drw2["Passed"].ToString() == "0")
                                        drw["Passed_" + strIndex] = false;
                                    else
                                        drw["Passed_" + strIndex] = true;
                                }
                                else
                                {
                                    drw["Exam2_" + strIndex] = drw2["Exam2"];
                                    drw["Summary2_" + strIndex] = drw2["Summary2"];
                                    drw["Exam3_" + strIndex] = drw2["Exam3"];
                                    drw["Summary3_" + strIndex] = drw2["Summary3"];
                                    drw["FinalExam_" + strIndex] = drw2["FinalExam"];
                                    drw["FinalSummary_" + strIndex] = drw2["FinalSummary"];

                                    if (drw2["Passed"].ToString() == "0")
                                        drw["Passed_" + strIndex] = false;
                                    else
                                        drw["Passed_" + strIndex] = true;
                                }

                                int intSpecialType = Convert.ToInt32(drw2["SpecialType"]);

                                if ((bolHaveNormalSubject && intSpecialType == Global.SubjectSpecialType.BinhThuong)
                                    || (!bolHaveNormalSubject && intSpecialType == Global.SubjectSpecialType.VanHoa))
                                {
                                    if (drw["FinalSummary_" + strIndex].ToString() != "")
                                    {
                                        int intUnitText = Convert.ToInt32(drw2["UnitText"]);
                                        dblTotalMark += Convert.ToDouble(drw["FinalSummary_" + strIndex]) * intUnitText;
                                        intUnitTextCount += intUnitText;
                                    }
                                }
                            }
                        }
                    }
                }

                // Tính TBC
                if (intUnitTextCount > 0)
                {
                    double dblSummaryLearningMark = 0;
                    if (uClass.RegulationID == 25)
                        dblSummaryLearningMark = Math.Round(dblTotalMark / intUnitTextCount, 2, MidpointRounding.AwayFromZero);
                    else
                        dblSummaryLearningMark = Math.Round(dblTotalMark / intUnitTextCount, 1, MidpointRounding.AwayFromZero);

                    drw["SummaryLearningMark"] = dblSummaryLearningMark;
                }

                // Xếp loại (theo service giống WinForms)
                drw["LearningLevel"] = SIM_SubjectMarkService.ToLearningLevel(drw, intRegulationIDCurrent, false);
            }
        }

        #endregion

        #region Render HTML

        /// <summary>
        /// Chuyển điểm sang chuỗi hiển thị (Đạt/K.đạt/Miễn)
        /// </summary>
        private string MarkToString(object mark, object passed, object isIgnore, bool isSecond)
        {
            if (isIgnore != null && isIgnore.ToString() != "" && Convert.ToBoolean(isIgnore))
                return (isSecond ? "<br>" : "") + "Miễn";

            if (mark == null || mark.ToString() == "")
                return "";

            double dblMark = -999;
            if (!double.TryParse(mark.ToString(), out dblMark))
                return "";

            string strValue = "";
            if (dblMark == -1)
                strValue = "M";
            else if (dblMark == 100)
                strValue = "K.đạt";
            else if (dblMark == 110)
                strValue = "Đạt";
            else
                strValue = dblMark.ToString("#,##0.0");

            string strBg = "";
            if (passed != null && passed.ToString() != "")
            {
                if (!Convert.ToBoolean(passed))
                    strBg = " background-color:Yellow; font-weight:bold; ";
            }

            string strColor = isSecond ? " color:Red; font-style: italic; " : "";

            return (isSecond ? "<br>" : "") + "<span style='" + strColor + strBg + "'>" + strValue + "</span>";
        }

        private string IntToString(object value)
        {
            if (value == null || value.ToString() == "")
                return "";

            return Convert.ToInt32(value).ToString("#,###");
        }

        private bool IsSummaryColumnVisible(string colName)
        {
            if (colName.Contains("Ethic")) return strShowEthic == "1";
            if (colName.Contains("TestAverage_")) return strShowTestAverage == "1";
            if (colName.Contains("Exam1_")) return strShowExam1 == "1";
            if (colName.Contains("Exam2_")) return strShowExam2 == "1";
            if (colName.Contains("Exam3_")) return strShowExam3 == "1";
            if (colName.Contains("FinalExam_")) return strShowExam == "1";
            if (colName.Contains("Summary1_")) return strShowSummary1 == "1";
            if (colName.Contains("Summary2_")) return strShowSummary2 == "1";
            if (colName.Contains("Summary3_")) return strShowSummary3 == "1";
            if (colName.Contains("FinalSummary_") && !colName.Contains("OtherFinalSummary_")) return strShowSummary == "1";
            return true;
        }

        private void ExportToHTML()
        {
            if (dtbClassSubject.Rows.Count > 60)
            {
                lblMsg.Text = "Lưu ý: Chương trình chỉ hiển thị tối đa 60 môn học!<br>Dữ liệu vượt hơn 60 môn học có thể không hiển thị!";
                lblMsg.Visible = true;
            }

            string str = "";
            string strRow = "";

            int n = dtbData.Rows.Count;

            for (int i = 0; i < n; i++)
            {
                DataRow drw = dtbData.Rows[i];

                string strCssRow = (i % 2 == 0) ? " class='Row' " : " class='RowAlt' ";

                strRow = "<td align='center'>" + (i + 1).ToString() + "</td>"
                        + "<td align='center'>" + drw["StudentCode"] + "</td>"
                        + "<td>" + drw["StudentFirstName"] + "</td>"
                        + "<td>" + drw["StudentLastName"] + "</td>"
                        + "<td align='center'>" + drw["BirthDateText"] + "</td>"
                        + "<td align='center'>" + drw["GenderText"] + "</td>";

                if (strShowEthic == "1")
                {
                    strRow += "<td align='center' class='col-summary2'>" + drw["EthicMark"] + "</td>"
                            + "<td align='center' class='col-summary2'>" + drw["EthicLevel"] + "</td>";
                }

                strRow += "<td align='center' class='col-summary3'><b>" + MarkToString(drw["SummaryLearningMark"], null, null, false) + "</b></td>"
                        + "<td align='center' class='col-summary3'>" + drw["LearningLevel"] + "</td>";

                for (int j = 1; j <= dtbClassSubject.Rows.Count; j++)
                {
                    if (intRegulationIDCurrent == 43 || intRegulationIDCurrent == 99 || intRegulationIDCurrent == 44)
                    {
                        // Tín chỉ: Chỉ hiện TKM, QĐChữ, QĐSố
                        if (strShowSummary == "1")
                            strRow += "<td align='center'>" + MarkToString(drw["FinalSummary_" + j], drw["Passed_" + j], null, false) + "</td>";
                        strRow += "<td align='center'>" + drw["LearningLevel_" + j] + "</td>";
                        strRow += "<td align='center' style='background-color:LightBlue'>" + MarkToString(drw["OtherFinalSummary_" + j], null, null, false) + "</td>";
                    }
                    else
                    {
                        if (strShowTestAverage == "1")
                            strRow += "<td align='center'>" + MarkToString(drw["TestAverage_" + j], null, null, false) + "</td>";

                        if (strShowExam1 == "1" && strShowExam2 == "1")
                        {
                            strRow += "<td align='center'>" + MarkToString(drw["Exam1_" + j], null, null, false)
                                        + MarkToString(drw["Exam2_" + j], null, null, true) + "</td>";
                        }
                        else
                        {
                            if (strShowExam1 == "1")
                                strRow += "<td align='center'>" + MarkToString(drw["Exam1_" + j], null, null, false) + "</td>";
                            if (strShowExam2 == "1")
                                strRow += "<td align='center'>" + MarkToString(drw["Exam2_" + j], null, null, false) + "</td>";
                        }

                        if (strShowSummary1 == "1" && strShowSummary2 == "1")
                        {
                            strRow += "<td align='center' class='col-summary'>" + MarkToString(drw["Summary1_" + j], drw["Passed_" + j], null, false)
                                        + MarkToString(drw["Summary2_" + j], drw["Passed_" + j], null, true) + "</td>";
                        }
                        else
                        {
                            if (strShowSummary1 == "1")
                                strRow += "<td align='center'>" + MarkToString(drw["Summary1_" + j], drw["Passed_" + j], null, false) + "</td>";
                            if (strShowSummary2 == "1")
                                strRow += "<td align='center'>" + MarkToString(drw["Summary2_" + j], drw["Passed_" + j], null, false) + "</td>";
                        }

                        if (strShowExam3 == "1")
                            strRow += "<td align='center'>" + MarkToString(drw["Exam3_" + j], null, null, false) + "</td>";
                        if (strShowSummary3 == "1")
                            strRow += "<td align='center'>" + MarkToString(drw["Summary3_" + j], drw["Passed_" + j], null, false) + "</td>";

                        if (strShowExam == "1")
                            strRow += "<td align='center' style='background-color:LightBlue'>" + MarkToString(drw["FinalExam_" + j], null, null, false) + "</td>";
                        if (strShowSummary == "1")
                            strRow += "<td align='center' style='background-color:LightBlue'>" + MarkToString(drw["FinalSummary_" + j], drw["Passed_" + j], null, false) + "</td>";
                    }
                }

                strRow = "<tr " + strCssRow + ">" + strRow + "</tr>\r\n";
                str += strRow;
            }

            // Header
            string strHead = BuildHeader();
            string strHead2 = BuildHeader2();

            str = "<div class='table-responsive fs-7 align-middle mt-2'>"
                + "<table class='table table-bordered table-hover TableCss' style='min-width:max-content'>"
                + "<thead class='align-middle text-wrap'>"
                + strHead + strHead2
                + "</thead>"
                + "<tbody>"
                + str
                + "</tbody>"
                + "</table>"
                + "</div>";

            lblContent.Text = str;
        }

        private string BuildHeader()
        {
            string strHead = "<tr class='fw-bold text-center table-primary'>"
                        + "<th colspan='6'>SINH VIÊN</th>";

            if (strShowEthic == "1")
                strHead += "<th colspan='2'>RÈN LUYỆN</th>";

            strHead += "<th colspan='2'>TỔNG KẾT</th>";

            for (int j = 1; j <= dtbClassSubject.Rows.Count; j++)
            {
                DataRow drwCol = dtbClassSubject.Rows[j - 1];
                string strSubjectName = Server.HtmlEncode(drwCol["SubjectName"].ToString());
                string strUnitText = drwCol["UnitText"].ToString();

                if (intRegulationIDCurrent == 43 || intRegulationIDCurrent == 99 || intRegulationIDCurrent == 44)
                    strHead += "<th colspan='3'>" + strSubjectName + "<br><span style='color:#da4a05'>(" + strUnitText + ")</span></th>";
                else
                {
                    int colSpan = 0;
                    if (strShowTestAverage == "1") colSpan++;
                    if (strShowExam1 == "1" || strShowExam2 == "1") colSpan++;
                    if (strShowSummary1 == "1" || strShowSummary2 == "1") colSpan++;
                    if (strShowExam3 == "1") colSpan++;
                    if (strShowSummary3 == "1") colSpan++;
                    if (strShowExam == "1") colSpan++;
                    if (strShowSummary == "1") colSpan++;

                    strHead += "<th colspan='" + colSpan.ToString() + "'>" + strSubjectName + "<br><span style='color:#da4a05'>(" + strUnitText + ")</span></th>";
                }
            }

            strHead += "</tr>";
            return strHead;
        }

        private string BuildHeader2()
        {
            string strHead2 = "<tr class='fw-bold text-center table-primary'>"
                            + "<th>STT</th>"
                            + "<th>Mã SV</th>"
                            + "<th>Họ đệm</th>"
                            + "<th>Tên</th>"
                            + "<th>Ngày sinh</th>"
                            + "<th>GT</th>";

            if (strShowEthic == "1")
            {
                strHead2 += "<th>Điểm</th>"
                          + "<th>Xếp loại</th>";
            }

            strHead2 += "<th>TBC</th>"
                      + "<th>Xếp loại</th>";

            for (int j = 1; j <= dtbClassSubject.Rows.Count; j++)
            {
                if (intRegulationIDCurrent == 43 || intRegulationIDCurrent == 99 || intRegulationIDCurrent == 44)
                {
                    strHead2 += "<th>TKM</th><th>QĐChữ</th><th>QĐSố</th>";
                }
                else
                {
                    if (strShowTestAverage == "1")
                        strHead2 += "<th>TBKT</th>";

                    if (strShowExam1 == "1" && strShowExam2 == "1")
                        strHead2 += "<th>Thi</th>";
                    else
                    {
                        if (strShowExam1 == "1") strHead2 += "<th>Thi1</th>";
                        if (strShowExam2 == "1") strHead2 += "<th>Thi2</th>";
                    }

                    if (strShowSummary1 == "1" && strShowSummary2 == "1")
                        strHead2 += "<th>TKM</th>";
                    else
                    {
                        if (strShowSummary1 == "1") strHead2 += "<th>TKM1</th>";
                        if (strShowSummary2 == "1") strHead2 += "<th>TKM2</th>";
                    }

                    if (strShowExam3 == "1") strHead2 += "<th>Thi3</th>";
                    if (strShowSummary3 == "1") strHead2 += "<th>TKM3</th>";
                    if (strShowExam == "1") strHead2 += "<th>Thi</th>";
                    if (strShowSummary == "1") strHead2 += "<th>TKM</th>";
                }
            }

            strHead2 += "</tr>";
            return strHead2;
        }

        private void ExportStatistic()
        {
            int[] arrStatisticCount = new int[6]; // Xuất sắc, Giỏi, Khá, TB khá, Trung bình, Yếu

            for (int i = 0; i < dtbData.Rows.Count; i++)
            {
                string strLevel = dtbData.Rows[i]["LearningLevel"].ToString();
                switch (strLevel)
                {
                    case "Xuất sắc": arrStatisticCount[0]++; break;
                    case "Giỏi": arrStatisticCount[1]++; break;
                    case "Khá": arrStatisticCount[2]++; break;
                    case "TB khá": arrStatisticCount[3]++; break;
                    case "Trung bình": arrStatisticCount[4]++; break;
                    case "Yếu":
                    case "Kém": arrStatisticCount[5]++; break;
                }
            }

            double dblCount = dtbData.Rows.Count > 0 ? dtbData.Rows.Count : 1;
            string[] strCaption = { "Xuất sắc", "Giỏi", "Khá", "TB khá", "Trung bình", "Yếu" };

            string strStat = "<div class='alert alert-info py-2 px-3 mt-2'><b>Thống kê:</b> ";
            for (int i = 0; i < 6; i++)
            {
                double percentage = Math.Round((double)arrStatisticCount[i] / dblCount * 100, 0);
                strStat += strCaption[i] + ": <b>" + arrStatisticCount[i].ToString() + " (" + percentage.ToString() + "%)</b>";
                if (i < 5) strStat += " | ";
            }
            strStat += "</div>";

            lblStatistic.Text = strStat;
            lblStatistic.Visible = true;
        }

        #endregion

        #region Export Excel

        private void ExportExcel()
        {
            Hashtable hstColumns = new Hashtable();
            Hashtable hstReplaceValues = new Hashtable();
            SIM_Branch obj = new SIM_Branch();

            try
            {
                // Tải lại dữ liệu để export
                SIM_SubjectMark objSubjectMark = new SIM_SubjectMark();
                SIM_Class_Subject objClassSubject = new SIM_Class_Subject();

                dtbClassSubject = objClassSubject.SearchSimpleList("@ClassID", uClass.ClassID,
                                            "@YearID", uYearSemester.YearID,
                                            "@Semester", uYearSemester.Semester,
                                            "@NotListSpecialType", null,
                                            "@IsOnlyForScheduling", 0);

                SIM_Student objStudent = new SIM_Student();
                dtbData = objStudent.GetDataTable("SIM_Student_SearchForSummary",
                                                "@ClassID", uClass.ClassID,
                                                "@YearID", uYearSemester.YearID,
                                                "@Semester", uYearSemester.Semester,
                                                "@IsShowAllStudent", rdoAll.Checked);

                if (chkIsFirst.Checked)
                    dtbSubjectMark = objSubjectMark.SearchFirst("@ClassID", uClass.ClassID);
                else
                    dtbSubjectMark = objSubjectMark.SearchFinal("@ClassID", uClass.ClassID);

                if (dtbData == null || dtbClassSubject == null || dtbSubjectMark == null)
                {
                    lblMsg.Text = "Việc lấy thông tin điểm bị lỗi!";
                    lblMsg.Visible = true;
                    return;
                }

